void ProjectAutosave::trim_history()
{
    try {
        std::set<std::string> live_attachments;
        for (const auto& attachment : m_persistence.document().attachments())
            if (!attachment.stored_name.empty())
                live_attachments.insert(attachment.relative_path());
        m_store->prune(kMaxVersions, kMaxBytes, live_attachments);
        m_warning.clear();
    } catch (const std::exception& error) {
        // The current head was already committed. A retention failure leaves
        // extra old data and must not misreport the current project as unsaved.
        m_warning = std::string("Local history cleanup failed: ") + error.what();
        BOOST_LOG_TRIVIAL(warning) << m_warning;
    }
}

bool ProjectAutosave::settle(bool wait)
{
    if (!m_worker.valid())
        return true;
    if (!wait && m_worker.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
        return false;
    try {
        m_worker.get();
        if (m_worker_kind == WorkerKind::Model) {
            m_committed_head = m_store->head_id();
            m_last_capture_input = std::move(m_inflight_capture_input);
            m_seen_model_input = m_last_capture_input;
            trim_history();
        }
        if (m_worker_kind == WorkerKind::Document)
            m_committed_semantic_revision = m_inflight_semantic_revision;
        m_worker_kind = WorkerKind::None;
        if (m_seen_semantic_revision == m_committed_semantic_revision)
            m_first_semantic_edit.reset();
        m_error.clear();
        // A main-thread edit may have landed while the worker wrote the
        // frozen revision. Probe again before saying the current model is saved.
        m_state = State::Saving;
        m_next_probe = Clock::now();
        return true;
    } catch (const std::exception& error) {
        m_worker_kind = WorkerKind::None;
        m_inflight_capture_input.clear();
        fail(error.what());
    } catch (...) {
        m_worker_kind = WorkerKind::None;
        m_inflight_capture_input.clear();
        fail("project version writer failed");
    }
    return false;
}

void ProjectAutosave::adopt_project()
{
    m_persistence.resolve_pending_boundary();
    const std::string id = m_persistence.document().project_id();
    if (m_store && m_store->project_id() == id)
        return;
    settle(true);
    m_store.reset();
    if (id.empty())
        throw std::runtime_error("open project has no identity");
    m_store = std::make_unique<ProjectVersionStore>(m_root, id);
    m_last_capture_input.clear();
    m_seen_model_input.clear();
    m_inflight_capture_input.clear();
    m_committed_head = m_store->head_id();
    m_committed_semantic_revision = m_committed_head.empty() ? 0 : m_persistence.document().doc_revision();
    m_seen_semantic_revision = m_persistence.document().doc_revision();
    m_last_semantic_edit = Clock::now();
    m_first_semantic_edit = m_seen_semantic_revision != m_committed_semantic_revision ?
        std::optional<Clock::time_point>(m_last_semantic_edit) : std::nullopt;
    const auto versions = m_store->history();
    m_project_name = versions.empty() ? std::string() : versions.back().project_name;
    m_revision = 0;
    for (const auto& version : versions)
        m_revision = std::max(m_revision, version.revision);
    m_state = State::Saving;
    m_next_probe = Clock::now();
}

bool ProjectAutosave::capture(bool wait_for_commit)
{
    if (!m_store)
        return false;
    std::filesystem::path metadata;
    try {
        const std::string id = ProjectVersionStore::new_id();
        metadata = m_store->pending_metadata_path(id);
        ++m_capture_attempts;
        const int result = m_plater.export_3mf(boost_path(metadata),
                                                SaveStrategy::Backup | SaveStrategy::Silence);
        if (result < 0)
            throw std::runtime_error("OrcaSlicer could not capture project metadata");
        const wxString source = m_plater.get_project_filename(".3mf");
        auto frozen = m_store->freeze(m_plater.model(), id, ++m_revision, m_persistence.document().dump(),
                                      source.ToUTF8().data(), m_persistence.timestamp());
        const auto& changes = m_persistence.document().changes();
        if (!changes.empty())
            frozen.version.change_seq = changes.back().seq;
        const auto semantic_revision = m_persistence.document().doc_revision();
        m_committed_semantic_revision = semantic_revision;
        if (m_seen_semantic_revision == semantic_revision)
            m_first_semantic_edit.reset();
        const std::string plater_name(m_plater.get_project_name().ToUTF8());
        frozen.version.project_name = m_project_name.empty() ? plater_name : m_project_name;
        if ((plater_name.empty() || plater_name == _L("Untitled").ToUTF8().data()) &&
            !m_plater.model().objects.empty())
            frozen.version.project_name = std::filesystem::u8path(m_plater.model().objects.front()->name).stem().u8string();
        m_project_name = frozen.version.project_name;
        if (m_store->unchanged(frozen)) {
            m_store->discard(frozen);
            m_last_capture_input = observed_input();
            m_seen_model_input = m_last_capture_input;
            m_seen_semantic_revision = semantic_revision;
            m_first_semantic_edit.reset();
            m_error.clear();
            m_state = State::Saved;
            return true;
        }
        m_state = State::Saving;
        if (wait_for_commit) {
            m_store->publish(std::move(frozen));
            m_committed_head = m_store->head_id();
            m_last_capture_input = observed_input();
            m_seen_model_input = m_last_capture_input;
            m_seen_semantic_revision = semantic_revision;
            m_first_semantic_edit.reset();
            trim_history();
            m_error.clear();
            m_state = State::Saved;
        } else {
            m_inflight_capture_input = observed_input();
            m_seen_model_input = m_inflight_capture_input;
            m_inflight_semantic_revision = semantic_revision;
            m_worker_kind = WorkerKind::Model;
            m_worker = std::async(std::launch::async, [this, frozen = std::move(frozen)]() mutable {
                m_store->publish(std::move(frozen));
            });
        }
        return true;
    } catch (const std::exception& error) {
        m_worker_kind = WorkerKind::None;
        if (!metadata.empty())
            std::filesystem::remove_all(metadata.parent_path());
        fail(error.what());
    }
    return false;
}

bool ProjectAutosave::persist_document(bool wait_for_commit)
{
    if (!m_store)
        return false;
    try {
        const std::string state = m_persistence.document().dump();
        const auto revision = m_persistence.document().doc_revision();
        m_state = State::Saving;
        if (wait_for_commit) {
            m_store->publish_document(state);
            m_committed_semantic_revision = revision;
            m_seen_semantic_revision = revision;
            m_first_semantic_edit.reset();
            m_error.clear();
            m_state = State::Saved;
        } else {
            m_inflight_semantic_revision = revision;
            m_worker_kind = WorkerKind::Document;
            m_worker = std::async(std::launch::async, [this, state] {
                m_store->publish_document(state);
            });
        }
        return true;
    } catch (const std::exception& error) {
        m_worker_kind = WorkerKind::None;
        fail(error.what());
        return false;
    }
}

void ProjectAutosave::tick()
{
    try {
        if (!m_resume_attempted) {
            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
            if (canvas == nullptr || !canvas->is_initialized())
                return;
            resume_latest();
        }
        adopt_project();
        if (!settle(false) && m_worker.valid())
            return;
        observe_document_change();
        const auto now = Clock::now();
        if (now < m_next_probe)
            return;
        m_next_probe = now + kProbeInterval;
        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
            m_persistence.document().doc_revision() <= 1) {
            m_state = State::Saved;
            return;
        }
        const std::string model_input = observed_input();
        if (model_input != m_seen_model_input) {
            m_seen_model_input = model_input;
            m_last_edit = now;
            m_state = State::Saving;
        }
        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
        const bool document_due = document_pending &&
            (now - m_last_semantic_edit >= kEditQuietPeriod ||
             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
        // A continuously edited model must not starve the current document.
        // Model capture also publishes the document, so a ready model still
        // takes precedence until the document's maximum delay is reached.
        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
            persist_document(false);
            return;
        }
        if (m_store->head_id().empty() || model_input != m_last_capture_input) {
            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
            if (canvas == nullptr || !canvas->is_initialized() ||
                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
                now - m_last_edit < kEditQuietPeriod)
                return;
            capture(false);
        } else if (document_pending) {
            if (!document_due)
                return;
            persist_document(false);
        } else {
            m_state = State::Saved;
            m_first_semantic_edit.reset();
        }
    } catch (const std::exception& error) {
        fail(error.what());
    }
}

ProjectVersionStore::Capture ProjectVersionStore::freeze(Model& live, const std::string& version_id,
                                                          std::uint64_t revision, std::string semantic_state,
                                                          std::string source_path, std::string created_at)
{
    require(safe_component(version_id), "invalid version id");
    const fs::path pending = m_root / "pending" / version_id;
    require(fs::exists(pending / "metadata.3mf"), "project metadata was not captured");
    require(valid_zip_entry(pending / "metadata.3mf", ""), "project metadata archive is invalid");
    publish_document(std::move(semantic_state));
    Capture capture;
    capture.version = {version_id, revision, 0, std::move(created_at), std::move(source_path), {}};
    capture.pending_dir = pending;
    capture.frozen = std::make_shared<Model>(live);
    for (std::size_t index = 0; index < live.objects.size(); ++index) {
        ModelObject& original = *live.objects[index];
        ModelObject& object = *capture.frozen->objects[index];
        const int backup_id = live.get_object_backup_id(original);
        capture.frozen->set_object_backup_id(object, backup_id);
        ObjectResource item;
        item.object_id = object.id().id;
        item.backup_id = backup_id;
        for (const ModelVolume* volume : object.volumes)
            item.facets += volume->mesh().facets_count();
        item.entry = entry_for(object);
        const std::string signature = signature_of(object, backup_id);
        capture.signatures[item.object_id] = signature;
        const auto previous = m_last_resources.find(item.object_id);
        const auto old_signature = m_last_signatures.find(item.object_id);
        if (previous != m_last_resources.end() && old_signature != m_last_signatures.end() &&
            old_signature->second == signature) {
            item.resource = previous->second.resource;
        } else {
            item.resource = {new_id(), item.entry};
            capture.changed_objects.push_back(item.object_id);
        }
        capture.version.objects.push_back(std::move(item));
    }
    validate_metadata(pending / "metadata.3mf", capture.version);
    return capture;
}

bool ProjectVersionStore::unchanged(const Capture& capture) const
{
    return !m_head_id.empty() && capture.signatures == m_last_signatures &&
           archive_digest(capture.pending_dir / "metadata.3mf") == m_last_metadata_digest;
}

void ProjectVersionStore::discard(const Capture& capture) const
{
    require(capture.pending_dir.parent_path() == m_root / "pending", "invalid pending version directory");
    fs::remove_all(capture.pending_dir);
}

void ProjectVersionStore::publish(Capture capture)
{
    require(capture.frozen != nullptr, "capture has no model");
    require(m_document_schema == 2, "project document must be durable before a model checkpoint");
    const fs::path pending = capture.pending_dir;
    validate_metadata(pending / "metadata.3mf", capture.version);
    fs::create_directories(pending / "new-resources");
    Model subset(*capture.frozen);
    for (std::size_t index = subset.objects.size(); index > 0; --index)
        if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(),
                      subset.objects[index - 1]->id().id) == capture.changed_objects.end())
            subset.delete_object(index - 1);
    subset.set_backup_path((pending / "writer-private").u8string());
    if (!subset.objects.empty()) {
        const fs::path changed_file = pending / "changed.3mf";
        const std::string changed_path = changed_file.u8string();
        StoreParams params;
        params.path = changed_path.c_str();
        params.model = &subset;
        params.config = nullptr;
        params.strategy = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::SkipAuxiliary | SaveStrategy::Zip64;
        require(store_bbs_3mf(params), "changed-object serialization failed");
        require(valid_zip_entry(changed_path, ""), "changed-object archive is invalid");
        mz_zip_archive input;
        mz_zip_zero_struct(&input);
        require(open_zip_reader(&input, changed_path), "cannot open changed-object archive");
        for (ObjectResource& object : capture.version.objects) {
            if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(), object.object_id) ==
                capture.changed_objects.end())
                continue;
            const auto subset_object = std::find_if(subset.objects.begin(), subset.objects.end(), [&object](const ModelObject* item) {
                return item->id().id == object.object_id;
            });
            require(subset_object != subset.objects.end(), "changed object was omitted from the serializer input");
            object.resource.entry = entry_for(**subset_object);
            const int entry_index = mz_zip_reader_locate_file(&input, object.resource.entry.c_str(), nullptr, 0);
            require(entry_index >= 0, "serialized object resource is missing: " + object.resource.entry);
            const fs::path target = pending / "new-resources" / (object.resource.id + ".zip");
            mz_zip_archive output;
            mz_zip_zero_struct(&output);
            require(open_zip_writer(&output, target.u8string()), "cannot create object resource");
            const bool written = mz_zip_writer_add_from_zip_reader(&output, &input, entry_index) &&
                                 mz_zip_writer_finalize_archive(&output);
            close_zip_writer(&output);
            require(written, "object resource write is incomplete: " + object.entry);
            validate_resource(target, object.resource.entry, object.facets);
            sync_file(target);
        }
        close_zip_reader(&input);
        fs::remove(changed_file);
    }
    for (const ObjectResource& object : capture.version.objects) {
        const fs::path path = fs::exists(pending / "new-resources" / (object.resource.id + ".zip")) ?
            pending / "new-resources" / (object.resource.id + ".zip") : resource_path(object.resource.id);
        require(fs::exists(path), "referenced object resource is missing");
    }
    checked_write(pending / "manifest.json", version_json(capture.version).dump(2));
    sync_file(pending / "metadata.3mf");
    sync_directory(pending);
    for (const ObjectResource& object : capture.version.objects) {
        const fs::path staged = pending / "new-resources" / (object.resource.id + ".zip");
        if (fs::exists(staged))
            atomic_replace(staged, resource_path(object.resource.id));
    }
    fs::remove_all(pending / "new-resources");
    fs::remove_all(pending / "writer-private");
    sync_directory(m_root / "resources");
